-- ExamGrind verified daily current-affairs desk: 1 November 2026.
-- Every item below was checked against the linked competent official record.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-01-advance-tax-devolution-states$$, $$2026-11-01$$,
$$Centre releases an advance tax-devolution instalment of Rs 1,09,019 crore to States$$,
$$The Union Government released Rs 1,09,019 crore as an advance instalment of tax devolution to State Governments ahead of the festive season. The Finance Ministry said the timing is intended to help States accelerate capital expenditure and finance development and welfare expenditure.$$,
$$This is a direct fiscal-federalism update. It tests the difference between tax devolution and a discretionary grant, and the fact that an advance instalment changes the timing of a transfer rather than creating a new scheme.$$,
$$Tax devolution is the constitutionally structured sharing of the net proceeds of specified Union taxes with States. An advance release improves State liquidity; it does not by itself alter the Finance Commission formula or the State's annual entitlement. Students should keep it separate from centrally sponsored scheme funding, loans and Article 275 grants.$$,
$$Union Government releases tax devolution of Rs 1,09,019 crore to State Governments$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330997&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-31$$,
$$["The advance instalment is Rs 1,09,019 crore.","Tax devolution transfers a share of Union tax proceeds to States.","The stated purpose is to support capital and development/welfare expenditure.","An advance instalment affects cash-flow timing, not the underlying devolution formula."]$$::jsonb,
$$[{"question":"Is an advance tax-devolution instalment the same as a new discretionary grant?","answer":"No. It is an earlier release of a State's tax-devolution entitlement; grants are a different fiscal-transfer channel."}]$$::jsonb,
$${"title":"How an advance devolution release works","steps":["Union taxes enter the divisible-pool framework.","The Finance Commission formula determines States' shares.","The Centre releases an instalment earlier than the usual schedule.","States receive liquidity for approved public expenditure."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-cotton-customs-exemption-extension$$, $$2026-11-01$$,
$$Customs-duty exemption on cotton imports extended to 31 December 2026$$,
$$The Government extended the existing customs-duty exemption on cotton imports by two months, from 31 October to 31 December 2026. The extension was issued by the Department of Revenue through Notification No. 35/2026-Customs dated 30 October.$$,
$$The notification is useful for questions on customs instruments, tariff policy and the cotton-textile value chain. It is an extension of an existing exemption, not a permanent abolition of import duty or a change in MSP policy.$$,
$$The Ministry of Textiles said the measure aims to support raw-material availability and competitive prices for domestic textile manufacturing while balancing farmers' interests. The legal instrument is a customs notification from the Department of Revenue; a ministry press release can explain the policy but does not replace the notification.$$,
$$Government of India extends Customs Duty Exemption on Cotton imports up to 31st December 2026$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330823&lang=1&reg=1$$,
$$Ministry of Textiles / Department of Revenue$$, $$2026-10-31$$,
$$["Notification No. 35/2026-Customs dated 30 October extended the exemption.","The revised end date is 31 December 2026.","The prior exemption was due to end on 31 October 2026.","The stated policy purpose includes cotton availability for domestic textiles."]$$::jsonb,
$$[{"question":"Did the 31 October announcement create a permanent zero-duty regime for cotton imports?","answer":"No. It extended the existing exemption for two months, up to 31 December 2026."}]$$::jsonb,
$${"title":"Customs-exemption timeline","steps":["An existing exemption has a stated expiry date.","Department of Revenue issues an amending customs notification.","The expiry is substituted with a later date.","Imports remain governed by the amended notification during that window."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-depa-ai-training-handbook$$, $$2026-11-01$$,
$$MeitY launches DEPA for AI Training Handbook$$,
$$The Ministry of Electronics and Information Technology launched the Handbook on Data Empowerment and Protection Architecture (DEPA) for AI Training. It presents a techno-legal approach to purpose-bound data collaboration for AI training while seeking to preserve privacy, confidentiality, intellectual-property interests and institutional control.$$,
$$This connects AI governance with data protection and digital public infrastructure. It is especially useful for distinguishing a framework or handbook from a binding statute, rule or data-sharing mandate.$$,
$$The official release describes contractual permissions, controlled computing environments, privacy safeguards and data provenance as parts of the approach. A core idea is that a model can be brought to controlled data rather than requiring unrestricted transfer of the underlying data. The handbook does not itself override applicable data-protection law or compel any custodian to share data.$$,
$$MeitY Launches DEPA for AI Training Handbook to Advance Trusted Data Collaboration for AI$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2330756&lang=1&reg=20$$,
$$Ministry of Electronics & IT / Press Information Bureau$$, $$2026-10-31$$,
$$["DEPA for AI Training is presented as a techno-legal framework.","It supports purpose-bound data collaboration for AI training.","The release identifies privacy, confidentiality, intellectual property and institutional control as concerns.","Data provenance helps trace the origin, permissions and use of data."]$$::jsonb,
$$[{"question":"Does the DEPA AI Training Handbook itself compel an institution to transfer all its data to an AI developer?","answer":"No. It describes controlled, permission-based collaboration; it is not a blanket compulsory-transfer rule."}]$$::jsonb,
$${"title":"Trusted AI-data collaboration","steps":["A data custodian sets permitted purpose and safeguards.","A controlled environment applies contractual and technical protections.","The model accesses approved data under those conditions.","Provenance records support traceability and accountability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-arai-ev-testing-facilities$$, $$2026-11-01$$,
$$ARAI inaugurates advanced battery and EV-powertrain testing facilities$$,
$$The Automotive Research Association of India (ARAI) inaugurated an Advanced Battery Laboratory and a two-dynamometer e-axle and EV powertrain test facility in Pune. The battery laboratory, developed under the Capital Goods Sector Phase II scheme with an approximately Rs 55 crore investment, is meant to support testing, validation, safety assessment and performance evaluation for electric and hybrid vehicles.$$,
$$The facilities make a concrete link between industrial policy, vehicle safety, certification and electric mobility. They also illustrate the difference between a testing institution's capability and a consumer subsidy or vehicle-approval rule.$$,
$$ARAI is an automotive research, testing and certification institution. The release says the new capacity can support design validation, certification and export-compliance testing. It also records an MoU for land transfer towards an Advanced Crash Test Facility; that proposed facility is distinct from the facilities inaugurated on 31 October.$$,
$$ARAI unveils key initiatives for safe, sustainable and future-ready mobility$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2330746&lang=2&reg=48$$,
$$Ministry of Heavy Industries / Press Information Bureau$$, $$2026-10-31$$,
$$["ARAI inaugurated an Advanced Battery Laboratory and an EV powertrain test facility.","The battery laboratory was developed under the Capital Goods Sector Phase II scheme.","The release gives the investment as approximately Rs 55 crore.","The facilities support testing, validation, safety assessment and certification-related work."]$$::jsonb,
$$[{"question":"Does opening an ARAI test facility itself grant an EV a certificate of roadworthiness?","answer":"No. The facility strengthens testing capacity; a vehicle still needs to meet the applicable approval and certification requirements."}]$$::jsonb,
$${"title":"From EV design to safe deployment","steps":["Manufacturers develop batteries and powertrains.","A testing institution evaluates performance and safety.","Results support validation and certification processes.","Compliant vehicles can proceed under applicable regulatory requirements."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-panchayat-cesl-ev-infrastructure-mou$$, $$2026-11-01$$,
$$Panchayati Raj Ministry and CESL partner on EV charging and battery swapping on Panchayat land$$,
$$The Ministry of Panchayati Raj signed an MoU with Convergence Energy Services Limited (CESL) to establish electric-vehicle charging and battery-swapping stations on Panchayat land across States and Union Territories. The partnership is designed to combine rural clean-mobility access with opportunities for Panchayats to raise own-source revenue.$$,
$$This is a useful local-government and energy-transition item. It shows how rural local bodies can use public assets for service infrastructure, but an MoU is not the same as an automatic nationwide installation or a statutory tax power.$$,
$$CESL is a wholly owned subsidiary of Energy Efficiency Services Limited under the Ministry of Power. Under the described arrangement, the Panchayati Raj Ministry will facilitate State-level coordination and site identification, while CESL will handle assessment, aggregation, supply, installation, commissioning, operation and maintenance. Suitability and implementation remain site-specific.$$,
$$MoU signed to set up EV charging and battery-swapping stations on Panchayat land$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330751&lang=2&reg=48$$,
$$Ministry of Panchayati Raj / Press Information Bureau$$, $$2026-10-31$$,
$$["The MoU parties are the Ministry of Panchayati Raj and CESL.","It covers charging and battery-swapping stations on Panchayat land.","CESL is a wholly owned subsidiary of EESL under the Ministry of Power.","The initiative seeks to support Panchayats' own-source revenue and rural EV access."]$$::jsonb,
$$[{"question":"Will every Panchayat receive a charging station merely because the MoU was signed?","answer":"No. The release describes site identification, assessment and implementation steps; deployment depends on suitable sites and execution."}]$$::jsonb,
$${"title":"Panchayat-land EV infrastructure","steps":["Panchayats identify potentially suitable community land.","State and Ministry coordination supports site selection.","CESL assesses demand and installs approved infrastructure.","Stations deliver EV services and may create local revenue."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-mizoram-pmgsy-iv-batch-one$$, $$2026-11-01$$,
$$Mizoram receives approval for 45 PMGSY-IV road works$$,
$$The Ministry of Rural Development approved 45 road works in Mizoram under PMGSY-IV Batch 1 for FY 2026-27. The package covers 509.54 km at an estimated cost of Rs 710.40 crore and is intended to provide all-weather connectivity to 48 habitations for the first time.$$,
$$This is a concrete State-level infrastructure decision under a national rural-roads programme. It is useful for testing the meaning of all-weather connectivity and for avoiding the mistake of treating an approval as a completed road or a direct cash benefit.$$,
$$The official release separately notes earlier PMGSY sanctions in the State, so the new Batch 1 approval should not be added to those older figures without care. Rural road connectivity can improve access to schools, health services and markets, but completion and use follow subsequent implementation stages.$$,
$$Mizoram Gets Approval for New Road Works under PMGSY-IV to Strengthen Rural Connectivity$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330725&lang=1&reg=3$$,
$$Ministry of Rural Development / Press Information Bureau$$, $$2026-10-31$$,
$$["The approval is under PMGSY-IV Batch 1 for FY 2026-27.","It covers 45 road works and 509.54 km in Mizoram.","The estimated cost is Rs 710.40 crore.","The works are intended to connect 48 habitations with all-weather roads for the first time."]$$::jsonb,
$$[{"question":"Does approval of a PMGSY road package prove that every listed road has already been completed?","answer":"No. Approval authorises the package; construction and operational connectivity occur through later implementation."}]$$::jsonb,
$${"title":"PMGSY approval to connectivity","steps":["The programme identifies eligible rural-connectivity needs.","The competent authority approves a road package.","Works proceed through procurement and construction.","Completed roads provide all-weather access to habitations."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-nvs-03-first-orbit-manoeuvre$$, $$2026-11-01$$,
$$ISRO completes NVS-03's first orbit manoeuvre after GSLV-F18 launch$$,
$$ISRO reported that GSLV-F18 injected NVS-03 into its initial transfer orbit on 30 October and that the spacecraft's planned first orbit manoeuvre was successfully completed on 31 October. NVS-03 is the third satellite in the next-generation navigation-satellite system intended to provide continuity for the IRNSS series.$$,
$$The update is a high-value space-technology item because it connects launch vehicles, transfer orbits, orbit raising and NavIC/IRNSS navigation services. It also tests why a successful launch is not the same as final placement in operational orbit.$$,
$$ISRO says the first manoeuvre used the Liquid Apogee Motor (LAM) and that further manoeuvres are planned to place the spacecraft in geostationary orbit at the 111.75 degrees East orbital slot. The satellite carries an indigenous atomic clock along with procured clocks and includes L1 in addition to L5 and S-band signals.$$,
$$Orbit manoeuvring of NVS-03 spacecraft$$,
$$https://www.isro.gov.in/Orbit_manoeuvring_of_NVS03_spacecraft.html$$,
$$Indian Space Research Organisation$$, $$2026-10-31$$,
$$["GSLV-F18 injected NVS-03 on 30 October 2026.","The first orbit manoeuvre was completed on 31 October using the LAM.","NVS-03 is the third satellite in the next-generation navigation system for IRNSS continuity.","Further manoeuvres are planned before placement at 111.75 degrees East in GSO."]$$::jsonb,
$$[{"question":"Was NVS-03 already in its final geostationary slot after the first manoeuvre?","answer":"No. ISRO said further manoeuvres were planned to place it in GSO at 111.75 degrees East."}]$$::jsonb,
$${"title":"Launch-to-navigation-orbit sequence","steps":["GSLV injects the satellite into an initial transfer orbit.","The spacecraft uses its onboard LAM for orbit raising.","Successive manoeuvres refine altitude and orbital position.","The satellite is placed in its target GSO slot for navigation-service continuity."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-01-cci-combination-approvals$$, $$2026-11-01$$,
$$CCI clears five proposed combinations across energy, telecom, finance and consumer sectors$$,
$$The Competition Commission of India published approvals for five proposed combinations on 31 October, including Adani Energy Solutions' proposed acquisition of IntelliSmart Infrastructure, Vega SAS's proposed stake acquisition in Vodafone Group, the Sapphire Foods–Devyani merger, Aditya Birla Renewables' proposed acquisition of Solenergi Power and MIH Payments' proposed shareholding acquisition in Navi.$$,
$$The group of orders is a practical competition-law update. It reinforces that the CCI examines notifiable combinations; an approval is a competition-law decision, not a guarantee of commercial completion or a sectoral licence.$$,
$$The IntelliSmart order concerns the proposed acquisition of 100% equity from NIIF and EESL, with both parties active in advanced metering infrastructure. The five announcements are separate approvals, not a single mega-merger. Students should distinguish CCI's competition review from SEBI's securities regulation, RBI licensing and the sector regulator's role.$$,
$$CCI approves acquisition of IntelliSmart Infrastructure by Adani Energy Solutions$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330819&lang=1&reg=3$$,
$$Competition Commission of India / Press Information Bureau$$, $$2026-10-31$$,
$$["CCI approved five separately announced proposed combinations on 31 October.","One approved proposal concerns Adani Energy Solutions acquiring IntelliSmart Infrastructure.","The IntelliSmart proposal envisages acquisition of 100% equity from NIIF and EESL.","CCI approval addresses competition law; it does not itself complete the transaction."]$$::jsonb,
$$[{"question":"Does CCI clearance mean a proposed acquisition has necessarily been completed?","answer":"No. It is a competition-law approval; closing still depends on the transaction terms and any other applicable requirements."}]$$::jsonb,
$${"title":"How a combination approval fits into a transaction","steps":["Parties propose a merger or acquisition.","A notifiable combination is reviewed by CCI.","CCI issues its competition-law decision.","The parties may close only after meeting transaction and other applicable conditions."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-01-advance-tax-devolution-states$$,
$$2026-11-01-cotton-customs-exemption-extension$$,
$$2026-11-01-depa-ai-training-handbook$$,
$$2026-11-01-arai-ev-testing-facilities$$,
$$2026-11-01-panchayat-cesl-ev-infrastructure-mou$$,
$$2026-11-01-mizoram-pmgsy-iv-batch-one$$,
$$2026-11-01-nvs-03-first-orbit-manoeuvre$$,
$$2026-11-01-cci-combination-approvals$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
